import { Field, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";

export const InputRequired = () => (
  <Field>
    <FieldLabel>
      Required Field <span className="text-error">*</span>
    </FieldLabel>
    <Input placeholder="This field is required" required />
    <FieldDescription>This field must be filled out.</FieldDescription>
  </Field>
);

import { InputRequired } from "../examples/input-required";

const Example = () => <InputRequired />;

export default Example;
